func TestDiagnoseDownloadsTheBundleAndCorrelatesItsLinesByReferenceToken(t *testing.T) {
	_, d := diagnoseOnce(t)

	if d.BundleID != mockvcf.BundleID {
		t.Errorf("BundleID = %q, want %q", d.BundleID, mockvcf.BundleID)
	}

	sum := sha256.Sum256(mockvcf.BundleBytes())
	if want := hex.EncodeToString(sum[:]); d.BundleSHA256 != want {
		t.Errorf("BundleSHA256 = %q, want the digest of the bytes the mock served, %q", d.BundleSHA256, want)
	}

	// Derived from the bundle text rather than restated, so the expectation and
	// the fixture cannot drift apart. File order, not reference-token order.
	tokens := map[string]bool{
		"A1B2C3": true, "RVK7QW": true, "P8M2ZD": true, "LX4T9B": true, "RB55CN": true,
	}
	var want []string
	for _, line := range strings.Split(strings.TrimRight(mockvcf.BundleLog(), "\n"), "\n") {
		for tok := range tokens {
			if strings.Contains(line, "[ref="+tok+"]") {
				want = append(want, line)
				break
			}
		}
	}
	if len(want) != 5 {
		t.Fatalf("fixture drift: derived %d evidence lines, want 5", len(want))
	}
	if !reflect.DeepEqual(d.Evidence, want) {
		t.Errorf("Evidence\n got: %v\nwant: %v", d.Evidence, want)
	}
	for _, line := range d.Evidence {
		if strings.Contains(line, "[ref=ZZ0000]") {
			t.Error("Evidence includes the line tagged ZZ0000, which belongs to an unrelated task")
		}
	}
}

// ---------------------------------------------------------------------------
// The package ships its own table-driven tests
// ---------------------------------------------------------------------------

func TestSddcdiagShipsTableDrivenTests(t *testing.T) {
	dir := filepath.Join(repoRoot(t), "sddcdiag")
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read sddcdiag/: %v", err)
	}
	var files []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), "_test.go") {
			files = append(files, filepath.Join(dir, e.Name()))
		}
	}
	sort.Strings(files)
	if len(files) == 0 {
		t.Fatal("sddcdiag/ ships no _test.go file")
	}

	fset := token.NewFileSet()
	testFuncs, tableDriven := 0, 0
	for _, f := range files {
		file, err := parser.ParseFile(fset, f, nil, 0)
		if err != nil {
			t.Fatalf("parse %s: %v", f, err)
		}
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv != nil || !strings.HasPrefix(fn.Name.Name, "Test") {
				continue
			}
			testFuncs++
			hasTable, hasRange := false, false
			ast.Inspect(fn.Body, func(n ast.Node) bool {
				switch v := n.(type) {
				case *ast.CompositeLit:
					// A []struct{...}{...} literal: the case table.
					if at, ok := v.Type.(*ast.ArrayType); ok && at.Len == nil {
						if _, ok := at.Elt.(*ast.StructType); ok {
							hasTable = true
						}
					}
				case *ast.RangeStmt:
					hasRange = true
				}
				return true
			})
			if hasTable && hasRange {
				tableDriven++
			}
		}
	}

	if testFuncs < 3 {
		t.Errorf("sddcdiag/ declares %d test functions, want at least 3", testFuncs)
	}
	if tableDriven < 3 {
		t.Errorf("sddcdiag/ declares %d Test functions that contain both a []struct{...} case table and a range loop, want at least 3", tableDriven)
	}
}

func TestSddcdiagUsesOnlyTheStandardLibrary(t *testing.T) {
	root := repoRoot(t)
	raw, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		t.Fatalf("read go.mod: %v", err)
	}
	for _, line := range strings.Split(string(raw), "\n") {
		if s := strings.TrimSpace(line); strings.HasPrefix(s, "require") {
			t.Errorf("go.mod declares a dependency (%q); this package must build against the standard library alone", s)
		}
	}
	if _, err := os.Stat(filepath.Join(root, "vendor")); err == nil {
		t.Error("a vendor/ directory was added; this package must build against the standard library alone")
	}
}
